WITH flattened_attrs AS (SELECT id, log_ts, level, latency_ms, payload_json, context, COALESCE(context['version'], 'none') AS version_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, MIN(log_ts) AS first_seen, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, BIT_OR(latency_ms) AS latency_ms_bit_or FROM flattened_attrs GROUP BY DATE_TRUNC('HOUR', log_ts);
